effect.shader:
const float TAU = 6.28318530718;

float hash21(vec2 p) {
    p = fract(p * vec2(127.1, 311.7));
    p += dot(p, p + 34.23);
    return fract(p.x * p.y);
}

void main() {
    vec4 original = texture(inputImg, acScreenNorm);

    vec2 uv = acScreenNorm * vec2(acAspect, 1.0);
    vec2 from = startPoint * vec2(acAspect, 1.0);
    vec2 to = endPoint * vec2(acAspect, 1.0);

    float t;
    if (shape == 1) {
        // Radial: a distância até o início, medida em "quantos raios".
        float radius = max(length(to - from), 0.0001);
        t = length(uv - from) / radius;
    } else if (shape == 2) {
        // Ângulo: uma volta completa em torno do início. Vira cone de cor.
        vec2 axis = to - from;
        float base = atan(axis.y, axis.x);
        float here = atan(uv.y - from.y, uv.x - from.x);
        t = fract((here - base) / TAU);
    } else {
        vec2 axis = to - from;
        float lengthSquared = max(dot(axis, axis), 0.0001);
        // Projeção do ponto sobre o eixo: dá exatamente "o quanto andei do
        // início para o fim", sem precisar de trigonometria.
        t = dot(uv - from, axis) / lengthSquared;
    }

    t = clamp(t, 0.0, 1.0);
    t = pow(t, max(rampCurve, 0.01));

    if (scatter > 0.0) {
        t = clamp(t + (hash21(acScreenNorm * acResolution) - 0.5) * scatter, 0.0, 1.0);
    }

    vec4 ramp = mix(startColor, endColor, t);
    fragColor = vec4(ramp.rgb, ramp.a * original.a);
}
